if (typeof window === 'undefined') {
    self.addEventListener("install", () => self.skipWaiting());
    self.addEventListener("activate", (e) => e.waitUntil(self.clients.claim()));
    self.addEventListener("fetch", (e) => {
        const { request } = e;
        if (request.cache === "only-if-cached" && request.mode !== "same-origin") return;
        e.respondWith(
            fetch(request).then((response) => {
                if (response.status === 0) return response;
                const newHeaders = new Headers(response.headers);
                // 💡ブラウザを完璧に騙して隔離状態にするための必須ヘッダー群
                newHeaders.set("Cross-Origin-Embedder-Policy", "require-corp");
                newHeaders.set("Cross-Origin-Opener-Policy", "same-origin");
                return new Response(response.body, {
                    status: response.status,
                    statusText: response.statusText,
                    headers: newHeaders,
                });
            }).catch((e) => console.error(e))
        );
    });
} else {
    (() => {
        // 💡もしすでに隔離状態（SharedArrayBufferが使える状態）なら何もしない
        if (window.crossOriginIsolated) return;

        if (window.navigator.serviceWorker) {
            // 自身のファイル名を取得して登録
            window.navigator.serviceWorker.register("./coi-serviceworker.js")
                .then((registration) => {
                    b("COOP/COEP Service Worker の登録に成功しました。");
                    
                    // 💡重要：登録が完了したら、サービスワーカーを強制適用させるためにページをリロードする
                    registration.addEventListener("updatefound", () => {
                        b("新しいサービスワーカーを検出。リロードします...");
                        window.location.reload();
                    });
                    if (registration.active && !window.navigator.serviceWorker.controller) {
                        b("サービスワーカーを有効化するため、ページを強制リロードします...");
                        window.location.reload();
                    }
                }).catch(err => {
                    console.error("サービスワーカー登録エラー:", err);
                });
        }
    })();
}
